import {icons} from '/ui-icons.js';
import '/navigation.js';
const $=id=>document.getElementById(id);
const sheet=document.createElement('link');sheet.rel='stylesheet';sheet.href='/sandbox-controls.css';document.head.append(sheet);
const iconize=(el,name,label)=>{if(!el)return;el.innerHTML=icons[name];el.setAttribute('aria-label',label);el.title=label;el.dataset.cue=label;el.classList.add('purpose-icon');};
$('b3-navigation')?.remove();$('b3-nav-toggle').onclick=()=>window.RanchNavigation.open();iconize($('nav-close'),'close','Close navigation');iconize($('b3-nav-toggle'),'menu','Navigation');iconize($('b3-nav-close'),'close','Close navigation');
const rail=document.createElement('div');rail.id='sandbox-icon-rail';rail.setAttribute('role','group');rail.setAttribute('aria-label','Sandbox controls');document.body.append(rail);
for(const [id,icon,label] of [['b3-world-menu','world','World'],['app-settings-toggle','settings','Appearance settings'],['b3-view','view','Camera and view']]){const b=$(id);iconize(b,icon,label);if(b)rail.append(b);}
const button=document.createElement('button');button.id='sandbox-scenarios';button.type='button';button.setAttribute('aria-haspopup','dialog');button.setAttribute('aria-expanded','false');iconize(button,'scenarios','Scenarios');rail.append(button);
const dialog=document.createElement('dialog');dialog.id='sandbox-scenario-drawer';dialog.setAttribute('aria-labelledby','sandbox-scenario-title');dialog.innerHTML=`<div class="purpose-drawer-head"><h2 id="sandbox-scenario-title">Scenarios</h2><button type="button" aria-label="Close scenarios">${icons.close}</button></div><a class="scenario-choice" href="/board3?scene=zombies"><span class="scenario-symbol">${icons.zombies}</span><span><strong>Archers vs Zombies</strong><small>Two cards · Four difficulties</small></span>${icons.right}</a><a class="scenario-choice" href="/sandbox/outbreak"><span class="scenario-symbol">${icons.zombies}</span><span><strong>Shared world actors</strong><small>Zombies, wizards, rabbits & nations</small></span>${icons.right}</a><a class="icon-credit" href="/ui-icon-licenses.txt" target="_blank" rel="noopener">Icon credits</a>`;document.body.append(dialog);
button.onclick=()=>{dialog.showModal();button.setAttribute('aria-expanded','true');dialog.querySelector('button').focus();window.RanchView?.changed();};dialog.querySelector('button').onclick=()=>dialog.close();dialog.onclose=()=>{button.setAttribute('aria-expanded','false');button.focus();window.RanchView?.changed();};dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
$('b3-scenarios')?.remove();
if($('b3-version'))$('b3-version').textContent='Sandbox · v1.7';
window.RanchView?.register('sandboxControls',()=>({version:1,controls:['Navigation','World','Appearance settings','Camera and view','Scenarios'],scenariosOpen:dialog.open,appearanceOpen:!!$('app-settings')?.open}));

const devButton=document.createElement('button');devButton.type='button';devButton.textContent='Dev';devButton.id='sandbox-dev-toggle';devButton.setAttribute('aria-label','Developer and quality');devButton.setAttribute('aria-haspopup','dialog');rail.append(devButton);
const dev=document.createElement('dialog');dev.id='sandbox-dev';dev.innerHTML=`<div class="purpose-drawer-head"><h2>Rendering</h2><button aria-label="Close rendering">${icons.close}</button></div><label>Quality<select id="sandbox-quality"><option value="eco">Eco · 1×</option><option value="balanced">Balanced · up to 1.5×</option><option value="high">High · up to 2×</option></select></label><label class="dev-check"><input type="checkbox" id="sandbox-stats"> Developer overlay</label><dl id="sandbox-dev-details"></dl>`;document.body.append(dev);
const hud=document.createElement('output');hud.id='sandbox-performance';hud.hidden=true;document.body.append(hud);
devButton.onclick=()=>{dev.querySelector('select').value=window.RanchPerformance.read().quality;dev.open?dev.close():dev.show();};dev.querySelector('button').onclick=()=>dev.close();dev.querySelector('select').onchange=e=>window.RanchPerformance.setQuality(e.target.value);dev.querySelector('input').onchange=e=>{hud.hidden=!e.target.checked;};
function updateDev(){if(document.hidden||(!dev.open&&hud.hidden)||!window.RanchPerformance)return;const v=window.RanchPerformance.read(),num=n=>Number(n).toLocaleString();hud.textContent=`${v.fps?v.fps+' FPS':'Idle'} · ${v.fps?v.frameMs+' ms/frame':'on demand'}\n${num(v.drawCalls)} calls · ${num(v.triangles)} triangles\n${v.width} × ${v.height} · ${v.pixelRatio.toFixed(2)}×`;
dev.querySelector('dl').innerHTML=[['FPS',v.fps||'Idle'],['Frame interval',v.fps?v.frameMs+' ms':'—'],['CPU submit',v.cpuSubmitMs+' ms'],['Draw calls',num(v.drawCalls)],['Triangles',num(v.triangles)],['Geometries',num(v.geometries)],['Textures',num(v.textures)],['Resolution',v.width+' × '+v.height]].map(([k,v])=>'<dt>'+k+'</dt><dd>'+v+'</dd>').join('');}setInterval(updateDev,500);
